  $('#lastScan').textContent=state.settings.last_scan?`${t('lastScan.prefix')}${state.settings.last_scan}${scanAdvice}`:'';
  $('#scanBtn').disabled=!!state.scan.running;$('#scanBtn').innerHTML=state.scan.running?`⟳ <span>${t('status.scanning')}</span>`:`⟳ <span>${t('btn.scan')}</span>`;
  document.body.classList.toggle('scanning',!!state.scan.running);$('#scanProgress').classList.toggle('hidden',!state.scan.running);
