function quickDialog(title,label,placeholder,submit,buttonLabel=t('dialog.save'),initialValue=''){const box=document.createElement('div');box.className='modal quick-modal';box.innerHTML=`<div class="modal-backdrop"></div><form class="modal-panel quick-panel"><div class="eyebrow">${t('nav.library')}</div><h2>${esc(title)}</h2><label>${esc(label)}<input class="dialog-input" autofocus placeholder="${esc(placeholder)}"></label><div class="dialog-actions"><button type="button" class="button subtle">${t('dialog.cancel')}</button><button class="button primary">${esc(buttonLabel)}</button></div></form>`;document.body.append(box);const input=$('.dialog-input',box);input.value=initialValue;input.focus();input.select();$('.button.subtle',box).onclick=()=>box.remove();box.onclick=e=>{if(e.target.classList.contains('modal-backdrop'))box.remove()};$('.quick-panel',box).onsubmit=e=>{e.preventDefault();const value=input.value.trim();box.remove();if(value)submit(value)};input.onkeydown=e=>{if(e.key==='Escape')box.remove()}}
function openTagRemoval(g){const own=state.settings.assignments?.[g.key]?.tags||[];if(!own.length){toast(t('tag.noneToRemove'));return}const box=document.createElement('div');box.className='modal quick-modal';box.innerHTML=`<div class="modal-backdrop"></div><section class="modal-panel quick-panel tag-remove-panel"><div class="eyebrow">${t('tag.eyebrow')}</div><h2>${t('tag.removeTitle')}</h2><p class="muted">${t('tag.removeDesc',esc(g.name))}</p><div class="tag-remove-list">${own.map(tag=>`<button class="tag-remove-choice" data-remove-tag="${esc(tag)}"><span>${esc(tag)}</span><b>−</b></button>`).join('')}</div><div class="dialog-actions"><button type="button" class="button subtle" data-close-dialog>${t('tag.close')}</button></div></section>`;document.body.append(box);box.onclick=async e=>{if(e.target.classList.contains('modal-backdrop')||e.target.closest('[data-close-dialog]')){box.remove();return}const choice=e.target.closest('[data-remove-tag]');if(!choice)return;try{await api('/api/game',{key:g.key,action:'tag_remove',value:choice.dataset.removeTag});box.remove();await refreshState();toast(t('tag.removed',choice.dataset.removeTag))}catch(err){toast(err.message)}}}
function openRemovalConfirmation(g){const action=g.uninstall?'uninstall':'delete';const box=document.createElement('div');box.className='modal quick-modal';box.innerHTML=`<div class="modal-backdrop"></div><section class="modal-panel quick-panel removal-panel" role="alertdialog" aria-modal="true" aria-labelledby="removalTitle"><div class="eyebrow">${t('remove.eyebrow')}</div><h2 id="removalTitle">${action==='uninstall'?t('remove.uninstallTitle'):t('remove.deleteTitle')}</h2><p>${action==='uninstall'?t('remove.uninstallDesc',esc(g.name)):t('remove.deleteDesc',esc(g.name))}</p><div class="removal-facts"><span>${t('remove.size')}</span><b>${size(g.size)}</b><span>${t('remove.path')}</span><b class="removal-path">${esc(g.path)}</b></div><div class="dialog-actions"><button type="button" class="button subtle" data-cancel-removal>${t('dialog.cancel')}</button><button type="button" class="button danger-confirm-button" data-confirm-removal>${action==='uninstall'?t('remove.uninstall'):t('remove.delete')}</button></div></section>`;document.body.append(box);const dismiss=()=>box.remove();box.onclick=async e=>{if(e.target.classList.contains('modal-backdrop')||e.target.closest('[data-cancel-removal]')){dismiss();return}if(!e.target.closest('[data-confirm-removal]'))return;const confirmButton=$('[data-confirm-removal]',box);confirmButton.disabled=true;confirmButton.textContent=action==='uninstall'?t('remove.opening'):t('remove.deleting');try{await api('/api/action',{key:g.key,action});dismiss();await refreshState();toast(action==='uninstall'?t('remove.uninstallDone'):t('remove.deleteDone'))}catch(err){confirmButton.disabled=false;confirmButton.textContent=action==='uninstall'?t('remove.uninstall'):t('remove.delete');toast(err.message)}};box.onkeydown=e=>{if(e.key==='Escape')dismiss()}}
const WHEEL_COLORS=['#6389ef','#7dd6bf','#efc66c','#d78cff','#fa8296','#56c6e8','#a9d36b','#ff9b55','#b2a2ff','#52c9a5','#f2a0b5','#8fb4ff'];
const picker={pool:[],query:'',spinning:false,shown:[],rotation:0,raf:0,canvas:null,ctx:null};
function pickerEntries(){if(picker.pool.length)return picker.pool.map(e=>({name:e.name,game:e.game||null}));return currentGames().map(g=>({name:g.name,game:g}))}
function openRandomPicker(){
  picker.pool=[];picker.shown=[];picker.rotation=0;picker.spinning=false;
  const box=document.createElement('div');box.className='modal quick-modal random-modal';
  box.innerHTML=`<div class="modal-backdrop" data-close-random></div><section class="modal-panel quick-panel random-panel" role="dialog" aria-modal="true" aria-labelledby="randomTitle">
    <div class="random-head"><div><div class="eyebrow">${t('nav.library')}</div><h2 id="randomTitle">${t('random.title')}</h2></div><button class="close-btn" data-close-random title="${t('tag.close')}" aria-label="${t('tag.close')}">×</button></div>
    <label class="random-search">${t('random.filterLabel')}<input class="dialog-input" id="randomQuery" placeholder="${t('random.filterPh')}"></label>
    <div class="random-custom"><input class="dialog-input" id="randomCustom" placeholder="${t('random.customPh')}" maxlength="60"><button class="button subtle" id="randomCustomAdd" type="button">＋</button></div>
    <div class="random-pool" id="randomPool"></div>
    <div class="random-candidates" id="randomCandidates"></div>
    <div class="random-wheel-wrap"><canvas id="randomWheel" width="640" height="640"></canvas><div class="random-pointer"></div></div>
    <div class="random-result muted" id="randomResult">${t('random.hint')}</div>
    <div class="dialog-actions"><button class="button primary" id="randomSpin">${t('random.spin')}</button></div>
  </section>`;
  document.body.append(box);
  const close=()=>{cancelAnimationFrame(picker.raf);box.remove()};
  box.onclick=e=>{if(e.target.closest('[data-close-random]'))close()};
  picker.canvas=$('#randomWheel',box);picker.ctx=picker.canvas.getContext('2d');
  const candidates=()=>{const q=$('#randomQuery',box).value.trim().toLocaleLowerCase('fr');const taken=new Set(picker.pool.map(e=>e.name.toLocaleLowerCase('fr')));return currentGames().filter(g=>!taken.has(g.name.toLocaleLowerCase('fr'))&&(!q||`${g.name} ${(g.tags||[]).join(' ')}`.toLocaleLowerCase('fr').includes(q)))};
  const renderChips=()=>{const chips=picker.pool.map((e,i)=>`<span class="pool-chip"><span class="pool-chip-name">${esc(e.name)}${e.game?'':` <small>${t('random.freeTag')}</small>`}</span><button data-unpool="${i}" title="${t('random.removeFromWheel')}">×</button></span>`).join('');const total=pickerEntries().length;$('#randomPool',box).innerHTML=chips||`<span class="muted" style="font-size:10px">${t('random.poolAll',total)}</span>`};
  const renderCandidates=()=>{const list=candidates().slice(0,60);$('#randomCandidates',box).innerHTML=list.map(g=>`<div class="random-candidate"><span>${esc(g.name)}<small>${esc(g.source)}</small></span><button data-pool="${esc(g.key)}" title="${t('random.addToWheel')}">＋</button></div>`).join('')||`<div class="muted" style="font-size:10px;padding:6px">${t('random.noCandidates')}</div>`};
  const addToPool=(name,game)=>{const clean=String(name||'').trim();if(!clean)return;if(picker.pool.some(e=>e.name.toLocaleLowerCase('fr')===clean.toLocaleLowerCase('fr'))){toast(t('random.alreadyIn'));return}picker.pool.push({name:clean,game:game||null});renderChips();renderCandidates()};
  $('#randomCandidates',box).onclick=e=>{const b=e.target.closest('[data-pool]');if(!b)return;const g=state.games.find(x=>x.key===b.dataset.pool);if(g)addToPool(g.name,g)};
  $('#randomPool',box).onclick=e=>{const b=e.target.closest('[data-unpool]');if(!b)return;picker.pool.splice(Number(b.dataset.unpool),1);renderChips();renderCandidates()};
  const addCustom=()=>{const input=$('#randomCustom',box);addToPool(input.value,null);input.value='';input.focus()};
  $('#randomCustomAdd',box).onclick=addCustom;
  $('#randomCustom',box).onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addCustom()}if(e.key==='Escape')close()};
  $('#randomQuery',box).oninput=()=>renderCandidates();
  $('#randomQuery',box).onkeydown=e=>{if(e.key==='Escape')close()};
  const shortName=name=>name.length>18?name.slice(0,17)+'…':name;
  const drawWheel=()=>{const ctx=picker.ctx,entries=picker.shown,n=entries.length,cx=320,cy=320,r=310;ctx.clearRect(0,0,640,640);ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle='#1a2231';ctx.fill();ctx.strokeStyle='#2a3345';ctx.lineWidth=6;ctx.stroke();if(!n)return;const seg=Math.PI*2/n;for(let i=0;i<n;i++){const a0=picker.rotation+i*seg,a1=a0+seg;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,a0,a1);ctx.closePath();ctx.fillStyle=WHEEL_COLORS[i%WHEEL_COLORS.length];ctx.fill();ctx.strokeStyle='rgba(8,12,20,.55)';ctx.lineWidth=4;ctx.stroke();ctx.save();ctx.translate(cx,cy);ctx.rotate(a0+seg/2);ctx.textAlign='right';ctx.textBaseline='middle';ctx.fillStyle='#fff';ctx.font='700 24px Inter,"Segoe UI",sans-serif';ctx.shadowColor='rgba(0,0,0,.6)';ctx.shadowBlur=8;ctx.fillText(shortName(entries[i].name),r-18,0);ctx.restore()}ctx.beginPath();ctx.arc(cx,cy,r*.17,0,Math.PI*2);ctx.fillStyle='#141a26';ctx.fill();ctx.strokeStyle='#ffffff26';ctx.lineWidth=5;ctx.stroke()};
  const showResult=e=>{const g=e.game;if(!g){$('#randomResult',box).innerHTML=`<div class="random-winner">🏆 ${esc(e.name)}</div><div class="muted" style="font-size:10px">${t('random.customNote')}</div>`;return}$('#randomResult',box).innerHTML=`<div class="random-winner">🏆 ${esc(g.name)}</div><div class="muted" style="font-size:10px">${esc(g.source)} · ${size(g.size)}</div><div class="random-result-actions"><button class="button subtle" id="randomOpen">${t('random.open')}</button><button class="button subtle" id="randomLaunch">${t('game.play')}</button></div>`;$('#randomOpen',box).onclick=()=>{close();openGame(g.key)};$('#randomLaunch',box).onclick=async()=>{try{await api('/api/action',{key:g.key,action:'launch'});toast(t('toast.gameLaunched',g.name))}catch(e){toast(e.message)}}};
  $('#randomSpin',box).onclick=()=>{if(picker.spinning)return;const full=pickerEntries();if(!full.length){toast(t('toast.noGames'));return}picker.shown=full.length>14?[...full].sort(()=>Math.random()-.5).slice(0,14):full;const w=Math.floor(Math.random()*picker.shown.length),n=picker.shown.length,seg=Math.PI*2/n,pointer=-Math.PI/2,from=picker.rotation,need=(pointer-w*seg-seg/2-from)%(Math.PI*2),wrapped=need<0?need+Math.PI*2:need,to=from+Math.PI*2*6+wrapped,dur=4200+Math.random()*800,t0=performance.now();picker.spinning=true;const btn=$('#randomSpin',box);btn.disabled=true;btn.textContent='…';const step=now=>{const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,4);picker.rotation=from+(to-from)*e;drawWheel();if(k<1){picker.raf=requestAnimationFrame(step)}else{picker.rotation=((to%(Math.PI*2))+Math.PI*2)%(Math.PI*2);picker.spinning=false;btn.disabled=false;btn.textContent=t('random.spin');drawWheel();showResult(picker.shown[w])}};picker.raf=requestAnimationFrame(step)};
  renderChips();renderCandidates();drawWheel();
}
