function manageCategories(){const categories=[...(state.settings.categories||[])];const box=document.createElement('div');box.className='modal quick-modal';box.innerHTML=`<div class="modal-backdrop"></div><section class="modal-panel quick-panel category-manager"><div class="eyebrow">${t('nav.library')}</div><h2>${t('cat.manageTitle')}</h2><p class="muted">${t('cat.manageDesc')}</p><div class="category-manager-list">${categories.map((name,i)=>`<div class="category-manager-row" data-index="${i}"><span class="category-grip" draggable="true" title="${t('cat.dragTitle')}" aria-label="${t('cat.dragTitle')}">⠿</span><b>${esc(name)}</b><button data-move="-1" title="${t('cat.up')}" ${i===0?'disabled':''}>↑</button><button data-move="1" title="${t('cat.down')}" ${i===categories.length-1?'disabled':''}>↓</button><button data-rename="1" title="${t('cat.rename')}">✎</button><button data-delete="1" title="${t('cat.delete')}">×</button></div>`).join('')||`<p class="muted">${t('cat.empty')}</p>`}</div><div class="dialog-actions"><button class="button subtle" data-close-dialog>${t('settings.done')}</button></div></section>`;document.body.append(box);const list=$('.category-manager-list',box);let dragged=-1;list.addEventListener('dragstart',e=>{const row=e.target.closest('.category-manager-row');if(!row||!e.target.closest('.category-grip')){e.preventDefault();return}dragged=Number(row.dataset.index);row.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragged))});list.addEventListener('dragend',()=>{$$('.category-manager-row',list).forEach(row=>row.classList.remove('dragging','drop-target'))});list.addEventListener('dragover',e=>{const row=e.target.closest('.category-manager-row');if(!row)return;e.preventDefault();$$('.category-manager-row',list).forEach(item=>item.classList.toggle('drop-target',item===row));e.dataTransfer.dropEffect='move'});list.addEventListener('drop',async e=>{const row=e.target.closest('.category-manager-row');if(!row)return;e.preventDefault();const source=dragged>=0?dragged:Number(e.dataTransfer.getData('text/plain')),target=Number(row.dataset.index);if(source<0||source===target)return;const [moved]=categories.splice(source,1);categories.splice(target,0,moved);try{await api('/api/category',{action:'reorder',categories});state.settings.categories=categories;box.remove();renderNav();manageCategories()}catch(err){toast(err.message)}});box.onclick=async e=>{if(e.target.classList.contains('modal-backdrop')||e.target.closest('[data-close-dialog]')){box.remove();return}const row=e.target.closest('[data-index]');if(!row)return;const i=Number(row.dataset.index);try{if(e.target.closest('[data-move]')){const j=i+Number(e.target.closest('[data-move]').dataset.move);[categories[i],categories[j]]=[categories[j],categories[i]];await api('/api/category',{action:'reorder',categories});state.settings.categories=categories;box.remove();renderNav();manageCategories()}else if(e.target.closest('[data-rename]')){quickDialog(t('cat.renameTitle'),t('cat.renameLabel'),t('cat.renamePh'),async name=>{try{await api('/api/category',{action:'rename',old:categories[i],name});box.remove();await refreshState();manageCategories()}catch(err){toast(err.message)}},t('dialog.save'),categories[i])}else if(e.target.closest('[data-delete]')){if(confirm(t('cat.deleteConfirm',categories[i]))){await api('/api/category',{action:'delete',name:categories[i]});box.remove();await refreshState();manageCategories()}}}catch(err){toast(err.message)}}}
function addFilter(){quickDialog(t('addFilter.title'),t('addFilter.tagLabel'),t('addFilter.tagPh'),tag=>quickDialog(t('addFilter.nameTitle'),t('addFilter.nameLabel'),tag,name=>api('/api/filter',{name,tag}).then(refreshState).catch(e=>toast(e.message))))}

document.addEventListener('click',e=>{
  const menuBtn=e.target.closest('[data-menu]');if(menuBtn){const game=state.games.find(g=>g.key===menuBtn.dataset.menu);if(game)showMenu(menuBtn,game);return}
  const action=e.target.closest('[data-action]');if(action){const g=state.games.find(x=>x.key===action.dataset.key);if(!g)return;if(action.dataset.action==='favorite'){api('/api/game',{key:g.key,action:'favorite'}).then(refreshState).catch(err=>toast(err.message))}else api('/api/action',{key:g.key,action:action.dataset.action}).catch(err=>toast(err.message));return}
  const store=e.target.closest('[data-store]');if(store){if(store.dataset.store)window.open(store.dataset.store,'_blank','noopener');return}
  const open=e.target.closest('[data-open-game]');if(open){openGame(open.dataset.openGame);return}
  if(state.menu&&!e.target.closest('.context-menu'))closeMenu();
});
